local ConfigList = {}

---@private
function LimitedTimeMonthGiftConfig:init()
    local config = FileUtil.getGameConfigFromCsv("pay_activity/limited_time_month_gift.csv", 3)
    for _, item in pairs(config or {}) do
        ---@class LimitedTimeMonthGiftConfigData
        local data = {
            id = tonumber(item.n_id),
            activityId = tonumber(item.n_activityId) or 0,
            giftName = tostring(item.s_giftName) or "",
            giftDesc = tostring(item.s_giftDesc) or "",
            initPrice = tonumber(item.n_initPrice) or 0,
            finalPrice = tonumber(item.n_finalPrice) or 0,
            roundId = tonumber(item.n_roundId) or 1,
            percent = tostring(item.s_percent) or "",
            limitCounts = tonumber(item.n_limitCounts) or 0,
        }
        data.boughtCounts = 0
        data.dataType = "month"
        data.giftKey = data.activityId .. "-" .. data.id
        local array = StringUtil.split(tostring(item.s_giftContent) or "", "#")
        data.giftContent = {}
        for _ , value in pairs(array) do
            table.insert(data.giftContent, tonumber(value))
        end
        table.insert(ConfigList, data)
    end
    table.sort(ConfigList, function(c1, c2)
        return c1.id < c2.id
    end)
end

