---@return LimitedTimeMonthGiftConfigData[]
function LimitedTimeMonthGiftConfig:getCfgsByRoundId(roundId)
    local cfgs = {}
    for _, cfg in pairs(ConfigList) do
        if cfg.roundId == roundId then
            table.insert(cfgs,  cfg)
        end
    end
    return cfgs
end

---@return LimitedTimeMonthGiftConfigData[]
function LimitedTimeMonthGiftConfig:getMaxRound()
    local maxRound = 1
    for _, cfg in pairs(ConfigList) do
        maxRound = math.max(cfg.roundId ,  maxRound)
